//! DAN-1909 network-client rule: a real TLS request, completed against a local
//! https server, through the same constructor the binaries use.
//!
//! The certificates are generated by `common::TestPki` on every run. Nothing is
//! committed.

mod common;

use std::sync::atomic::Ordering;
use std::time::Duration;

use common::{Reply, TestPki, TestServer};
use hatate_core::net::{ErrorKind, NetClient, NetConfig, NetRequest};

const T: Duration = Duration::from_secs(10);

/// The verifier's PASS names this test.
#[tokio::test]
async fn real_tls_request_completes_through_the_binaries_constructor() {
    let pki = TestPki::generate();
    let server = TestServer::https(&pki, |_| Reply::ok("hello over tls")).await;

    // The one constructor: `NetClient::new` installs the provider and builds the client.
    let client =
        NetClient::new(NetConfig::default().with_root_certificate_der(pki.ca_der.clone())).unwrap();
    let resp = client
        .send(NetRequest::get(&server.url("/ping"), T).unwrap())
        .await
        .unwrap();

    assert_eq!(resp.status.as_u16(), 200);
    assert_eq!(resp.text(), "hello over tls");
    assert_eq!(resp.url.scheme(), "https");
    let seen = server.recorded();
    assert_eq!(seen.len(), 1);
    assert_eq!(seen[0].target, "/ping");
    assert_eq!(
        seen[0].header("user-agent"),
        Some("hatate-linux/1.0 (+https://github.com/nostrenz/hatate-iqdb-tagger)")
    );

    // The pooled TLS connection is reused: three requests, one handshake.
    for _ in 0..2 {
        client
            .send(NetRequest::get(&server.url("/again"), T).unwrap())
            .await
            .unwrap();
    }
    assert_eq!(server.request_count(), 3);
    assert_eq!(server.connections.load(Ordering::SeqCst), 1);
}

#[tokio::test]
async fn a_certificate_from_an_untrusted_authority_is_rejected() {
    let pki = TestPki::generate();
    let server = TestServer::https(&pki, |_| Reply::ok("never delivered")).await;

    // No extra root: the throw-away CA is not in the system trust store.
    let client = NetClient::new(NetConfig::default()).unwrap();
    let err = client
        .send(NetRequest::get(&server.url("/x"), T).unwrap())
        .await
        .unwrap_err();
    assert_eq!(err.kind(), ErrorKind::Tls, "{err}");
    assert_eq!(
        server.request_count(),
        0,
        "no request was sent over the rejected connection"
    );
}

#[tokio::test]
async fn certificate_checks_can_be_switched_off_for_a_self_signed_hydrus() {
    let pki = TestPki::generate();
    let server = TestServer::https(&pki, |_| Reply::ok("hydrus")).await;
    let client = NetClient::new(NetConfig::default().without_tls_verification()).unwrap();
    let resp = client
        .send(NetRequest::get(&server.url("/"), T).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.text(), "hydrus");
}

#[tokio::test]
async fn a_certificate_for_another_name_is_rejected() {
    // The leaf covers localhost and 127.0.0.1; asking for another name must fail
    // even though the CA is trusted.
    let pki = TestPki::generate();
    let server = TestServer::https(&pki, |_| Reply::ok("x")).await;
    let client =
        NetClient::new(NetConfig::default().with_root_certificate_der(pki.ca_der.clone())).unwrap();
    let url = format!("https://127.0.0.2:{}/", server.addr.port());
    let err = client
        .send(NetRequest::get(&url, Duration::from_secs(3)).unwrap())
        .await
        .unwrap_err();
    assert!(
        matches!(
            err.kind(),
            ErrorKind::Connect | ErrorKind::Tls | ErrorKind::Timeout
        ),
        "{err}"
    );
}
